1|// Global paragraph ids, like `c12p34`. Chapter and paragraph are positive integers.
2|export function paragraphId(chapter: number, para: number): string {
3|  if (!Number.isInteger(chapter) || chapter < 1 || !Number.isInteger(para) || para < 1) {
4|    throw new RangeError(`paragraphId needs positive integers, got ${chapter}, ${para}`);
5|  }
6|  return `c${chapter}p${para}`;
7|}
8|
9|const ID_RE = /^c(\d+)p(\d+)$/;
10|
11|// Parse an id back into chapter/para, or null when it is not a valid id.
12|export function parseParagraphId(id: string): { chapter: number; para: number } | null {
13|  const m = ID_RE.exec(id);
14|  if (!m) return null;
15|  const chapter = Number(m[1]);
16|  const para = Number(m[2]);
17|  if (!Number.isSafeInteger(chapter) || chapter < 1 || !Number.isSafeInteger(para) || para < 1) {
18|    return null;
19|  }
20|  return { chapter, para };
