1|import { passages } from "./passages.mjs";
2|
3|const key = process.env.META_API_KEY;
4|if (!key) throw new Error("META_API_KEY is not set");
5|console.log("key present:", Boolean(process.env.META_API_KEY));
6|
7|// Split each passage on sentences into 3 paragraphs, ordinals n from 1.
8|const paras = [];
9|for (const p of passages) {
10|  const sentences = p.text.replace(/\s+/g, " ").match(/[^.!?"]+[.!?]["”]?/g).map((s) => s.trim());
11|  const per = Math.ceil(sentences.length / 3);
12|  for (let i = 0; i < sentences.length; i += per) {
13|    paras.push({ n: paras.length + 1, from: p.id, text: sentences.slice(i, i + per).join(" ") });
14|  }
15|}
16|const inputText = paras.map((p) => `[${p.n}] ${p.text}`).join("\n");
17|const N = paras.length;
18|console.log(`paragraphs=${N}: ${paras.map((p) => `${p.n}(${p.from})`).join(" ")}`);
19|
20|const schema = {
21|  type: "object",
22|  properties: {
23|    scenes: {
24|      type: "array",
25|      items: {
26|        type: "object",
27|        properties: {
28|          first_n: { type: "integer" },
29|          last_n: { type: "integer" },
30|          title: { type: "string" },
31|          evidence: { type: "string" },
32|          characters: { type: "array", items: { type: "string" } },
33|        },
34|        required: ["first_n", "last_n", "title", "evidence", "characters"],
35|        additionalProperties: false,
36|      },
37|    },
38|  },
39|  required: ["scenes"],
40|  additionalProperties: false,
41|};
42|
43|// Tiny manual validator, no deps.
44|function validate(v) {
45|  const errs = [];
46|  if (typeof v !== "object" || v === null || Array.isArray(v)) return ["root not an object"];
47|  if (Object.keys(v).join() !== "scenes") errs.push("root keys != [scenes]");
48|  if (!Array.isArray(v.scenes)) return [...errs, "scenes not an array"];
49|  v.scenes.forEach((s, i) => {
50|    const keys = Object.keys(s).sort().join();
51|    if (keys !== "characters,evidence,first_n,last_n,title") errs.push(`scene ${i} keys=[${keys}]`);
52|    if (!Number.isInteger(s.first_n) || !Number.isInteger(s.last_n)) errs.push(`scene ${i} n not integer`);
53|    if (typeof s.title !== "string" || !s.title) errs.push(`scene ${i} bad title`);
54|    if (typeof s.evidence !== "string" || !s.evidence) errs.push(`scene ${i} bad evidence`);
55|    if (!Array.isArray(s.characters) || !s.characters.every((c) => typeof c === "string")) {
56|      errs.push(`scene ${i} bad characters`);
57|    }
58|  });
59|  return errs;
60|}
61|
62|function checkCoverage(scenes) {
63|  const seen = new Map();
64|  for (const s of scenes) {
65|    if (!Number.isInteger(s.first_n) || !Number.isInteger(s.last_n) || s.first_n > s.last_n) {
66|      return { ok: false, detail: "inverted or non-integer range" };
67|    }
68|    for (let n = s.first_n; n <= s.last_n; n++) seen.set(n, (seen.get(n) ?? 0) + 1);
69|  }
70|  const missing = [];
71|  const overlap = [];
72|  for (let n = 1; n <= N; n++) {
73|    if (!seen.has(n)) missing.push(n);
74|    else if (seen.get(n) > 1) overlap.push(n);
75|  }
76|  const extra = [...seen.keys()].filter((n) => n < 1 || n > N);
77|  const ok = missing.length === 0 && overlap.length === 0 && extra.length === 0;
78|  return { ok, detail: `missing=[${missing}] overlap=[${overlap}] extra=[${extra}]` };
79|}
80|
81|async function run(label) {
82|  const t0 = Date.now();
83|  const res = await fetch("https://api.meta.ai/v1/chat/completions", {
84|    method: "POST",
85|    headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
86|    body: JSON.stringify({
87|      model: "muse-spark-1.3-contributor",
88|      messages: [
89|        {
90|          role: "user",
91|          content:
92|            `Split these ${N} numbered paragraphs into scenes. Return first_n/last_n ` +
93|            `ordinals, a short title, one verbatim evidence quote under 20 words, and ` +
94|            `characters per scene.\n${inputText}`,
95|        },
96|      ],
97|      response_format: { type: "json_schema", json_schema: { name: "scene_split", strict: true, schema } },
98|    }),
99|  });
100|  const ms = Date.now() - t0;
101|  const body = await res.json().catch(() => null);
102|  if (!res.ok) {
103|    console.log(`${label}: FAIL status=${res.status} latency_ms=${ms} error=${body?.error?.message ?? "(empty)"}`);
104|    return { usd: 0 };
105|  }
106|  const content = body.choices?.[0]?.message?.content ?? "";
107|  let parsed = null;
108|  let parseOk = false;
109|  try {
110|    parsed = JSON.parse(content);
111|    parseOk = true;
112|  } catch {
113|    parseOk = false;
114|  }
115|  const verrs = parseOk ? validate(parsed) : ["unparseable"];
116|  const coverage = parseOk ? checkCoverage(parsed.scenes) : { ok: false, detail: "unparseable" };
117|  let evOk = true;
118|  let evDetail = "";
119|  if (parseOk) {
120|    const flat = passages.map((p) => p.text.replace(/\s+/g, " ")).join(" ");
121|    for (const [i, s] of parsed.scenes.entries()) {
122|      const words = s.evidence.split(/\s+/).filter(Boolean).length;
123|      if (!flat.includes(s.evidence.replace(/\s+/g, " ")) || words >= 20) {
124|        evOk = false;
125|        evDetail += ` scene${i}(words=${words})`;
126|      }
127|    }
128|  }
129|  const u = body.usage ?? {};
130|  const cached = u.cached_input_tokens ?? u.prompt_cache_hit_tokens ?? u.cached_tokens ?? 0;
