43|// Tiny manual validator, no deps.
44|function validate(v) {
45|  const errs = [];
46|  if (typeof v !== "object" || v === null || Array.isArray(v)) return ["root not an object"];
47|  if (Object.keys(v).join() !== "scenes") errs.push("root keys != [scenes]");
48|  if (!Array.isArray(v.scenes)) return [...errs, "scenes not an array"];
49|  v.scenes.forEach((s, i) => {
50|    const keys = Object.keys(s).sort().join();
51|    if (keys !== "characters,evidence,first_n,last_n,title") errs.push(`scene ${i} keys=[${keys}]`);
52|    if (!Number.isInteger(s.first_n) || !Number.isInteger(s.last_n)) errs.push(`scene ${i} n not integer`);
53|    if (typeof s.title !== "string" || !s.title) errs.push(`scene ${i} bad title`);
54|    if (typeof s.evidence !== "string" || !s.evidence) errs.push(`scene ${i} bad evidence`);
55|    if (!Array.isArray(s.characters) || !s.characters.every((c) => typeof c === "string")) {
56|      errs.push(`scene ${i} bad characters`);
57|    }
58|  });
59|  return errs;
